// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        ReentrantAttacker attacker = new ReentrantAttacker();
        attacker.setTarget(address(c));
        vm.deal(address(attacker), amount);
        bool ok;
        try attacker.attack(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: for any admissible deposit amount, a full withdrawal
        // driven through withdrawAll (even with a re-entrant counterparty)
        // succeeds and leaves the contract holding exactly the deposited ETH.
        assertTrue(ok && address(c).balance == 0);
    }
}

contract ReentrantAttacker {
    ReentrancyDAO c;

    function setTarget(address target) external { c = ReentrancyDAO(target); }

    function attack(uint256 amount) external payable {
        c.deposit{value: amount}();
        c.withdrawAll();
    }

    receive() external payable {
        // re-enter: in the correct version credit is already zeroed, so this
        // call is a no-op; in the buggy version it underflows and reverts,
        // bubbling up and failing the outer call.
        c.withdrawAll();
    }
}
